    },
    {
        "zhuang": "Gou dwg daj Gvangjsih daeuj.",
        "zh": "我是从广西来的。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux ndwn bakdou dwg daxmeh gou.",
        "zh": "站在门口的是我妈妈。",
        "source": "textbook"
    },
    {
        "zhuang": "De lwg daxlungz gou.",
        "zh": "他是我伯父的孩子。",
        "source": "textbook"
    },
    {
        "zhuang": "Daxmeh gou vunz laj mbanj.",
        "zh": "我妈是乡下人。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux byaij gvaq daeuj dahcej gou.",
        "zh": "走过来的是我姐姐。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz ndaem duz de.",
        "zh": "黑的那头是他的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gonjbit gwnz daiz gonj duh gou.",
        "zh": "桌子上的笔是我的。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz rap cuengq roengz daeuj.",
        "zh": "把担子放下来。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bonjsaw neix sik bae.",
        "zh": "把这本书撕了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aendou gven ndei.",
        "zh": "把门关好。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aenmauh duet bae.",
        "zh": "把帽子脱掉。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aenriep saeg seuq bae.",
        "zh": "把蚊帐洗干净了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bak daej cug hwnjdaeuj.",
        "zh": "把袋子口扎起来。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aen vanj de swiq bae.",
        "zh": "把那个碗洗了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aen vanj de bae swiq.",
        "zh": "拿那个碗去洗了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bat raemx de bok bae.",
        "zh": "把那盆水倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bat raemx de daeuj bok.",
        "zh": "把那盆水倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz buh de daenj lo.",
        "zh": "把那件衣服穿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz buh de daeuj daenj lo.",
        "zh": "拿那件衣服来穿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ok ndit lo.",
        "zh": "出太阳了",
        "source": "textbook"
    },
    {
        "zhuang": "Hwnj dangz le.",
        "zh": "上课了",
        "source": "textbook"
    },
    {
        "zhuang": "Ok rumz lo.",
        "zh": "刮风了。",
        "source": "textbook"
    },
    {
        "zhuang": "Doek fwn lo.",
        "zh": "下雨了",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk!",
        "zh": "站着",
